// Ported from the Node app's Sequelize model Expense (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class ExpenseConfiguration : IEntityTypeConfiguration<Expense>
{
    public void Configure(EntityTypeBuilder<Expense> builder)
    {
        builder.ToTable("expenses", t =>
        {
            t.HasCheckConstraint("CK_expenses_method", "[method] IN (N'cash', N'card', N'upi', N'bank')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Category).HasColumnName("category").HasColumnType("nvarchar(80)").HasMaxLength(80).IsRequired();
        builder.Property(e => e.Description).HasColumnName("description").HasColumnType("nvarchar(255)").HasMaxLength(255);
        builder.Property(e => e.Amount).HasColumnName("amount").HasColumnType("decimal(10,2)");
        builder.Property(e => e.SpentOn).HasColumnName("spent_on").HasColumnType("date");
        builder.Property(e => e.Method).HasColumnName("method").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'cash'");
        builder.Property(e => e.Reference).HasColumnName("reference").HasColumnType("nvarchar(60)").HasMaxLength(60);
    }
}
